\begin{lemma}
\label{lemma:W-queries}
Let $W_1,\dots,W_k$ be a collection of pairwise disjoint sets of vertices. Let $q(i_1,z_1),\dots,q(i_N,z_N)$ be a set of queries of the form $q(i,z)\equiv$`` given an index $i\in\{1,\dots,k\}$ and a vertex $z$, find the greatest vertex $w\in W_i$ such that $w\leq z$". Then, Algorithm~\ref{algorithm:W-queries} answers all those queries in $O(n+N)$ time. 
\end{lemma}

\begin{algorithm}[t!]
\caption{\textsf{Given a collection $W_1,\dots,W_k$ of pairwise disjoint sets of vertices, answer a set of queries $q(i_1,z_1),\dots,q(i_N,z_N)$, where $q(i_t,z_t)$, for every $t\in\{1,\dots,N\}$, asks for the greatest vertex $w\in W_{i_t}$ such that $w\leq z_t$.}}
\label{algorithm:W-queries}
\LinesNumbered
\DontPrintSemicolon
\tcp{$W_1,\dots,W_k$ is a collection of pairwise disjoint sets of vertices}
\ForEach{$i\in\{1,\dots,k\}$}{
  sort $W_i$ in decreasing order\;
}
\ForEach{$i\in\{1,\dots,k\}$}{
  initialize $Q(i)\leftarrow\emptyset$\;
}
\ForEach{$t\in\{1,\dots,N\}$}{
  insert a tuple $(z_t,t)$ into $Q(i_t)$\;
}
\tcp{$Q(i)$ contains a tuple of the form $(z,t)$ if and only if the query $q(i_t,z_t)$ has $i_t=i$ and $z_t=z$. The first component of a tuple in $Q(i)$ stores the vertex of the respective query, and the second component stores a pointer to the query. The information, that we have to search in the set $W_i$ for the answer to this query, is given precisely by the index $i$ of this bucket of tuples}
\ForEach{$i\in\{1,\dots,k\}$}{
  sort $Q(i)$ in decreasing order w.r.t. the first component of its elements\; 
}
\ForEach{$i\in\{1,\dots,k\}$}{
\label{line:W-queries-for}
  let $w$ be the first element of $W_i$\;
  let $p$ be the first element of $Q(i)$\;
  \While{$p\neq\bot$}{
    let $p=(z,t)$\;
    \While{$w\neq\bot$ \textbf{and} $w>z$}{
      $w\leftarrow\mathit{next}_{W_i}(w)$\;
    }
    the answer to $q(i_t,z_t)$ is $w$\;
    $p\leftarrow\mathit{next}_{Q(i)}(p)$\;
  }
}
\end{algorithm}

\begin{lemma}
\label{lemma:type-3b-cases}
Let $u,v,w$ be three vertices $\neq r$ such that $w$ is proper ancestor of $v$ and $v$ is a proper ancestor of $u$, and let $e$ be a back-edge. Then $C'=\{(u,p(u)),(v,p(v)),(w,p(w)),e\}$ is a $4$-cut if and only if one of the following is true. (See Figure~\ref{figure:type3b}.)
\begin{enumerate}[label=(\arabic*)]
\item{$e\in B(u)\cap B(v)\cap B(w)$ and $B(v)\setminus\{e\}=(B(u)\setminus\{e\})\sqcup(B(w)\setminus\{e\})$}
\item{$e\in B(w)$, $e\notin B(v)\cup B(u)$, and $B(v)=B(u)\sqcup(B(w)\setminus\{e\})$}
\item{$e\in B(u)$, $e\notin B(v)\cup B(w)$, and $B(v)=(B(u)\setminus\{e\})\sqcup B(w)$}
\item{$e\in B(v)$ and $B(v)=(B(u)\sqcup B(w))\sqcup\{e\}$}
\end{enumerate}
\end{lemma}

Let $u,v,w$ be three vertices $\neq r$ such that $w$ is proper ancestor of $v$, $v$ is a proper ancestor of $u$, and there is a back-edge $e\in B(u)\cap B(v)\cap B(w)$ such that $B(v)\setminus\{e\}=(B(u)\setminus\{e\})\sqcup(B(w)\setminus\{e\})$ and $M(B(v)\setminus\{e\})=M(B(w)\setminus\{e\})$. By Lemma~\ref{lemma:type-3b-cases}, we have that $C=\{(u,p(u)),(v,p(v)),(w,p(w)),e\}$ is a $4$-cut; we call this a Type-3$\beta$ii-$1$ $4$-cut.

\begin{lemma}
\label{lemma:type3-b-ii-1-info}
Let $u,v,w$ be three vertices such that $(u,v,w)$ induces a Type-3$\beta$ii-$1$ $4$-cut, and let $e$ be the back-edge of the $4$-cut induced by $(u,v,w)$. Then $e=(\mathit{lowD}(u),\mathit{low}(u))$. Furthermore, $\mathit{low}(u)<w$, $\mathit{low}_2(u)\geq w$, $\mathit{high}(u)=\mathit{high}(v)$, $w$ is an ancestor of $\mathit{high}(v)$ and $M(w)=M(v)$. Finally, if $u'$ is a vertex such that $u\geq u'\geq v$ and $\mathit{high}(u')=\mathit{high}(v)$, then $u'$ is an ancestor of $u$.
\end{lemma}

Now let $v\neq r$ be a vertex with $\mathit{nextM}(v)\neq\bot$. Let $S$ be the segment of $H(\mathit{high}(v))$ that contains $v$ and is maximal w.r.t. the property that its elements are related as ancestor and descendant (i.e., we have $S=S(v)$). Then we let $U_1(v)$ denote the collection of all vertices $u\in S$ such that either $(1)$ $u$ is a proper descendant of $v$ with $\mathit{nextM}(v)>\mathit{low}_2(u)\geq\mathit{lastM}(v)$, or $(2)$ $u$ is the lowest proper descendant of $v$ in $S$ such that $\mathit{low}_2(u)\geq\mathit{nextM}(v)$.

\begin{lemma}
\label{lemma:type3-b-ii-1-U}
Let $(u,v,w)$ be a triple of vertices that induces a Type-3$\beta ii$-$1$ $4$-cut. Then $u\in U_1(v)$.
\end{lemma}

\begin{algorithm}[H]
\caption{\textsf{Compute the sets $U_1(v)$, for all vertices $v$ such that $\mathit{nextM}(v)\neq\bot$}}
\label{algorithm:type3-b-ii-1-U}
\LinesNumbered
\DontPrintSemicolon
\ForEach{vertex $x$}{
  compute the collection $\mathcal{S}(x)$ of the segments of $H(x)$ that are maximal w.r.t. the property
  that their elements are related as ancestor and descendant\;
}
\ForEach{$v\neq r$ such that $\mathit{nextM}(v)\neq\bot$}{
  set $U_1(v)\leftarrow\emptyset$\;
}
\ForEach{vertex $x$}{
  \ForEach{segment $S\in\mathcal{S}(x)$}{
    let $v$ be the first vertex in $S$\;
    \While{$v\neq\bot$ \textbf{and} $\mathit{nextM}(v)=\bot$}{
      $v\leftarrow\mathit{next}_S(v)$\;
    }
    \lIf{$v=\bot$}{\textbf{continue}}
    let $u\leftarrow\mathit{prev}_S(v)$\;
    \While{$v\neq\bot$}{
      \While{$u\neq\bot$ \textbf{and} $\mathit{low}_2(u)<\mathit{lastM}(v)$}{
        $u\leftarrow\mathit{prev}_S(u)$\;
      }
      \While{$u\neq\bot$ \textbf{and} $\mathit{low}_2(u)<\mathit{nextM}(v)$}{
        insert $u$ into $U_1(v)$\;
        $u\leftarrow\mathit{prev}_S(u)$\;
      }
      \If{$u\neq\bot$}{
        insert $u$ into $U_1(v)$\;
      }
      $v\leftarrow\mathit{next}_S(v)$\;
      \While{$v\neq\bot$ \textbf{and} $\mathit{nextM}(v)=\bot$}{
        $v\leftarrow\mathit{next}_S(v)$\;
      }      
    }
  }
}
\end{algorithm}

\begin{lemma}
\label{lemma:algorithm:type3-b-ii-1-U}
Algorithm~\ref{algorithm:type3-b-ii-1-U} correctly computes the collections of vertices $U_1(v)$, for all $v\neq r$ with $\mathit{nextM}(v)\neq\bot$. Furthermore, it has a linear-time implementation.
\end{lemma}

\begin{lemma}
\label{lemma:type3-b-ii-1-criterion}
Let $u,v,w$ be three vertices $\neq r$ such that $u$ is a proper descendant of $v$, $v$ is a proper descendant of $w$, $\mathit{high}(u)=\mathit{high}(v)$, $M(w)=M(v)$, $w\leq\mathit{low}_2(u)$, $\mathit{low}(u)<w$, and $\mathit{bcount}(v)=\mathit{bcount}(u)+\mathit{bcount}(w)-1$. Then there is a back-edge $e\in B(u)\cap B(v)\cap B(w)$ such that $B(v)\setminus\{e\}=(B(u)\setminus\{e\})\sqcup(B(w)\setminus\{e\})$.
\end{lemma}

\begin{lemma}
\label{lemma:type3-b-ii-1-greatest-w}
Let $(u,v,w)$ be a triple of vertices that induces a Type-3$\beta$ii-$1$ $4$-cut. Then $w$ is the greatest proper ancestor of $v$ with $M(w)=M(v)$ and $w\leq\mathit{low}_2(u)$.
\end{lemma}

\begin{algorithm}[H]
\caption{\textsf{Compute all Type-3$\beta ii$-$1$ $4$-cuts}}
\label{algorithm:type3-b-ii-1}
\LinesNumbered
\DontPrintSemicolon
\ForEach{vertex $v\neq r$ such that $\mathit{nextM}(v)\neq\bot$}{
\label{line:type-3-b-ii-1-for}
  compute the set $U_1(v)$\;
}
\ForEach{vertex $v\neq r$ such that $\mathit{nextM}(v)\neq\bot$}{
  \ForEach{$u\in U_1(v)$}{
    let $w$ be the greatest proper ancestor of $v$ such that $w\leq\mathit{low}_2(u)$ and $M(w)=M(v)$\;
    \label{line:type-3-b-ii-1-w}
    \If{$\mathit{low}(u)<w$ \textbf{and} $\mathit{bcount}(v)=\mathit{bcount}(u)+\mathit{bcount}(w)-1$}{
    \label{line:type-3-b-ii-1-cond}
      mark $\{(u,p(u)),(v,p(v)),(w,p(w)),(\mathit{lowD}(u),\mathit{low}(u))\}$ as a $4$-cut\;
      \label{line:type-3-b-ii-1-mark}
    }
  }
}
\end{algorithm}
